#pragma once
void renderBattle(int width,int height){uint32_t t;const auto&s=battleScene(battleLog,millis()-actionStarted,t);int f=s.frame;BattleRound empty={};const auto&r=s.index<battleLog.count?battleLog.rounds[s.index]:empty;int rw=previewPixels.empty()?pets[previewPet].width:previewW,rh=previewPixels.empty()?pets[previewPet].height:previewH;double fraction=t/500.0;
 if(battleLog.dungeon){canvas.setFont(&fonts::Font0);canvas.setTextDatum(top_left);canvas.setTextSize(1);canvas.setTextColor(ink);canvas.drawString("F"+String(dungeonFloorPlayed)+"  HP "+String(s.own)+"/10  ENEMY "+String(s.rival)+"/"+String(battleLog.initialRival),16,6);}
 auto own=[&](String kind="Walk 1",bool flip=true){petSprite(4,(16-height)/2,kind,flip,0);};auto enemy=[&](String kind="Walk 1",bool flip=false){previewSprite(12,(16-rh)/2,kind,flip,0);};
 auto hp=[&](int value,int x){int maximum=x==0?10:battleLog.initialRival;int bars=battleLog.dungeon?(value*5+maximum-1)/maximum:value;for(int i=0;i<std::min(5,bars);i++)for(int xx=0;xx<2;xx++)for(int yy=0;yy<2;yy++)pixel(x+xx,14-i*3+yy,ink);};
 auto shot=[&](int x,int attack,bool reverse,int count){if(count==2){projectile(x,0,attack,reverse);projectile(x,8,attack,reverse);}else projectile(x,4,attack,reverse);};
 auto impact=[&](bool reverse){bool invert=(t/80)%2==1;for(int y=0;y<16;y++)for(int x=0;x<32;x++)if((bool)care_hit[y*32+(reverse?31-x:x)]!=invert)pixel(x,y,ink);};
 if(f>=40){int n=f-40;if(n<4){hp(s.own,0);own(n%4>=2?"Attack":"Walk 2");}else{hp(s.rival,30);enemy((n-4)%4>=2?"Attack":"Walk 2");}return;}
 bool showOwn=f<=2||(f>=13&&f<=19)||(f>=29&&f<=32),showRival=(f>=3&&f<=12)||(f>=24&&f<=27);if(showOwn&&!(f>=15&&f<=17&&r.hitB))hp(s.own,0);if(showRival&&!(f>=5&&f<=7&&r.hitA))hp(s.rival,30);
 if(f==0)own();else if(f<=2){own("Attack");shot((int)std::floor(4+width+(f-1+fraction)*6+.5),activeAttack,false,r.shotsA);}else if(f<=4){enemy();shot((int)std::floor(4-(5-f-fraction)*6+.5),activeAttack,false,r.shotsA);}else if(f<=9){if(!r.hitA)enemy("Walk 1",true);else if(f<=7)impact(false);else enemy(f==8?"Injured 1":"Injured 2");}else if(f==10)enemy();else if(f<=12){enemy("Attack");shot((int)std::floor(4-(f-11+fraction)*6+.5),previewAttack,true,r.shotsB);}else if(f<=14){own();shot((int)std::floor(4+width+(15-f-fraction)*6+.5),previewAttack,true,r.shotsB);}else if(f<=19){if(!r.hitB)own("Walk 1",false);else if(f<=17)impact(true);else own(f==18?"Injured 1":"Injured 2");}else if(f>=24&&f<=27)enemy(f%2==0?"Injured 1":"Injured 2");else if(f>=29&&f<=32)own(f%2==1?"Injured 1":"Injured 2");
}
